+    match rust_env_info.get_rustup_rustc_version(context) {
+        Outcome::RustcVersion(rustc_version) => {
+            format_rustc_version(rustc_version, config.version_format)
+        }
+        Outcome::RustupNotWorking | Outcome::ToolchainUnknown => {
