+fn get_toolchain_version(
+    context: &Context,
+    _config: &RustConfig,
+    rust_env_info: &RustToolingEnvironmentInfo,
+) -> Option<String> {
+    type Outcome = RustupRunRustcVersionOutcome;
+
+    let default_host_triple = rust_env_info
+        .get_rustup_settings(context)
+        .default_host_triple()
+        .or_else(|| guess_host_triple());
